34	bool DeviceDriver::connectDevice(QString serial, bool isIndepedentDriver)
35	{
36	    if(!isIndepedentDriver) {
37	        if(activeDriver && activeDriver != this) {
38	            activeDriver->disconnect();
39	        }
40	    }
41	    if(connectTo(serial)) {
42	        if(!isIndepedentDriver) {
43	            activeDriver = this;
44	        }
45	        return true;
46	    } else {
47	        return false;
48	    }
49	}
