66	Sparam DeviceDriver::VNAMeasurement::toSparam(int ports) const
67	{
68	    if(ports == 0) {
69	        // determine number of ports by highest available S parameter
70	        for(const auto &m : measurements) {
71	            if(!m.first.startsWith("S")) {
72	                // something else we can not handle
73	                continue;
74	            }
75	            int to = m.first.mid(1,1).toUInt();
76	            int from = m.first.mid(2,1).toUInt();
77	            if(to > ports) {
78	                ports = to;
79	            }
80	            if(from > ports) {
81	                ports = from;
82	            }
83	        }
84	    }
85	    // create S paramters
86	    auto S = Sparam(ports);
87	    // fill data
88	    for(const auto &m : measurements) {
89	        if(!m.first.startsWith("S")) {
90	            // something else we can not handle
91	            continue;
92	        }
93	        int to = m.first.mid(1,1).toUInt();
94	        int from = m.first.mid(2,1).toUInt();
95	        S.set(to, from, m.second);
96	    }
97	    return S;
98	}
99	
100	void DeviceDriver::VNAMeasurement::fromSparam(Sparam S, std::vector<unsigned int> portMapping)
101	{
102	    if(portMapping.size() == 0) {
103	        // set up default port mapping
104	        for(unsigned int i=1;i<=S.ports();i++) {
105	            portMapping.push_back(i);
106	        }
107	    }
108	    for(unsigned int i=0;i<portMapping.size();i++) {
109	        for(unsigned int j=0;j<portMapping.size();j++) {
110	            QString name = "S"+QString::number(i+1)+QString::number(j+1);
111	            if(measurements.count(name)) {
112	                measurements[name] = S.get(portMapping[i], portMapping[j]);
113	            }
114	        }
115	    }
116	}
117	
118	DeviceDriver::VNAMeasurement DeviceDriver::VNAMeasurement::interpolateTo(const DeviceDriver::VNAMeasurement &to, double a)
119	{
120	    VNAMeasurement ret;
121	    ret.frequency = frequency * (1.0 - a) + to.frequency * a;
122	    ret.dBm = dBm * (1.0 - a) + to.dBm * a;
123	    ret.Z0 = Z0 * (1.0 - a) + to.Z0 * a;
124	    for(auto m : measurements) {
125	        if(to.measurements.count(m.first) == 0) {
126	            throw std::runtime_error("Nothing to interpolate to, expected measurement +\""+m.first.toStdString()+"\"");
127	        }
128	        ret.measurements[m.first] = measurements[m.first] * (1.0 - a) + to.measurements.at(m.first) * a;
129	    }
130	    return ret;
131	}
