161	
162	void DeviceDriver::Info::subset(const DeviceDriver::Info &info)
163	{
164	    if (info.firmware_version != firmware_version) {
165	        firmware_version = "Mixed";
166	    }
167	    if (info.hardware_version != hardware_version) {
168	        hardware_version = "Mixed";
169	    }
170	
171	    Limits.VNA.ports += info.Limits.VNA.ports;
172	    Limits.VNA.minFreq = std::max(Limits.VNA.minFreq, info.Limits.VNA.minFreq);
173	    Limits.VNA.maxFreq = std::min(Limits.VNA.maxFreq, info.Limits.VNA.maxFreq);
174	    Limits.VNA.mindBm = std::max(Limits.VNA.mindBm, info.Limits.VNA.mindBm);
175	    Limits.VNA.maxdBm = std::min(Limits.VNA.maxdBm, info.Limits.VNA.maxdBm);
